# Experimento de truncado (feature 006, T047): sobrevive el mensaje de sistema cuando Ollama quita mensajes antiguos
# porque el prompt no cabe en num-ctx? Una sola sesion con la plantilla extractor, cuyo mensaje de sistema exige un objeto
# JSON con las claves entidades, fechas y resumen: 10 turnos con un parrafo largo distinto (unas 250 palabras) y un turno
# final corto. Si el sistema se conserva, la respuesta del turno final (que es una frase corta) sigue siendo ese JSON.
#
# El script NO puede cambiar el num-ctx del backend: -NumCtx solo se anota en cada fila y debe coincidir con
# SPRING_AI_OLLAMA_CHAT_NUM_CTX del contenedor (hay que reiniciar el backend entre corridas, ver el quickstart).
# Con 2048 y 4096 el prompt acaba superando el contexto; con 8192 se espera que quepa (control).
# Por turno se guarda: numCtx, turno, http, promptTokens, historyMessages, answerIsJson, answerHasKeys.
#   answerIsJson   (estricta)  la respuesta es un objeto JSON valido con las claves entidades, fechas y resumen.
#   answerHasKeys  (relajada)  el texto de la respuesta contiene "entidades", "fechas" y "resumen". Es la columna decisiva:
#                              llama3.2:3b suele cortar el JSON sin la llave final (experimento D).
# Escribe experimento_truncado_ctx<NumCtx>.csv. La meseta es la senal de que el prompt no cabe: promptTokens deja de crecer
# (variacion menor al 1%) mientras historyMessages sigue subiendo (ver experimento_e.ps1).
param(
    [Parameter(Mandatory = $true)][int]$NumCtx,
    [string]$OutDir = (Join-Path $PSScriptRoot 'resultados')
)
. (Join-Path $PSScriptRoot 'comun.ps1')

$umbralMeseta = 0.01   # promptTokens varia menos del 1% respecto al turno anterior

function Entero($v) { if ($null -eq $v -or "$v" -eq '') { $null } else { [int]$v } }

# Meseta: promptTokens varia menos del 1% mientras historyMessages sigue subiendo.
function Hay-Meseta($ant, $act) {
    $pa = Entero $ant.promptTokens; $pc = Entero $act.promptTokens
    $ha = Entero $ant.historyMessages; $hc = Entero $act.historyMessages
    return ($null -ne $pa -and $null -ne $pc -and $null -ne $ha -and $null -ne $hc -and $pa -gt 0 -and [math]::Abs($pc - $pa) -lt ($umbralMeseta * $pa) -and $hc -gt $ha)
}

# Estricta: la respuesta entera es un objeto JSON con las tres claves.
function Es-Json([string]$texto) {
    try {
        $o = $texto | ConvertFrom-Json
        $n = @($o.PSObject.Properties.Name)
        return ($null -ne $o -and ($n -contains 'entidades') -and ($n -contains 'fechas') -and ($n -contains 'resumen'))
    } catch { return $false }
}

# Relajada: el texto contiene las tres claves entre comillas.
function Tiene-Claves([string]$texto) {
    return ($texto.Contains('"entidades"') -and $texto.Contains('"fechas"') -and $texto.Contains('"resumen"'))
}

