$final = Texto 'Tom\u00e1s Rivas firm\u00f3 el contrato en Alicante el 4 de junio de 2025 con la empresa Mediterr\u00e1nea Obras.'

$sessionId = "exp-trunc-$(Get-Date -Format 'yyyyMMddHHmmss')-$NumCtx"
$params = @{ temperature = 0.0; numPredict = 200; seed = 42 }
$inicio = Get-Date

Calentar
$preguntas = @($parrafos) + @($final)
$rows = @()
$anterior = $null
$turnoMeseta = $null
foreach ($i in 1..$preguntas.Count) {
    $r = Invoke-Chat $preguntas[$i - 1] $params 'extractor' $sessionId
    $texto = [string]$r.answer
    $fila = [pscustomobject]@{
        numCtx          = $NumCtx
        turno           = $i
        http            = $r.http
        promptTokens    = $r.promptTokens
        historyMessages = $r.historyMessages
        answerIsJson    = (Es-Json $texto)
        answerHasKeys   = (Tiene-Claves $texto)
    }
    Write-Host ("num-ctx {0}  turno {1}/{2}  http {3}  promptTokens {4}  historyMessages {5}  answerIsJson {6}  answerHasKeys {7}" -f `
        $NumCtx, $i, $preguntas.Count, $r.http, $r.promptTokens, $r.historyMessages, $fila.answerIsJson, $fila.answerHasKeys)
    $rows += $fila
    if ($r.http -ne 200) { Write-Host "AVISO: turno $i con http $($r.http): no es una respuesta valida." }
    if ($null -eq $turnoMeseta -and $anterior -and (Hay-Meseta $anterior $fila)) {
        $turnoMeseta = $i
        Write-Host ("AVISO: turno {0}: promptTokens se estanca en {1} (antes {2}) mientras historyMessages sube ({3} a {4}): Ollama esta quitando mensajes antiguos." -f `
            $i, $fila.promptTokens, $anterior.promptTokens, $anterior.historyMessages, $fila.historyMessages)
    }
    $anterior = $fila
}
Guardar $rows (Join-Path $OutDir "experimento_truncado_ctx$NumCtx.csv")

# Resumen: turno de la meseta y reparto de answerHasKeys antes y despues de ella, y en el turno final corto.
$largos = @($rows | Where-Object { [int]$_.turno -le $parrafos.Count })
function Reparto($filas) { "{0} de {1}" -f @($filas | Where-Object { $_.answerHasKeys }).Count, @($filas).Count }
Write-Host ''
Write-Host "Resumen num-ctx ${NumCtx}:"
if ($null -eq $turnoMeseta) {
    Write-Host '  meseta: ninguna'
    Write-Host ('  answerHasKeys en los turnos largos: {0}' -f (Reparto $largos))
} else {
    Write-Host "  meseta: turno $turnoMeseta"
    Write-Host ('  answerHasKeys antes de la meseta: {0}' -f (Reparto @($largos | Where-Object { [int]$_.turno -lt $turnoMeseta })))
    Write-Host ('  answerHasKeys desde la meseta: {0}' -f (Reparto @($largos | Where-Object { [int]$_.turno -ge $turnoMeseta })))
}
$ult = $rows[-1]
Write-Host ('  turno final corto: answerHasKeys {0}, answerIsJson {1}' -f $ult.answerHasKeys, $ult.answerIsJson)
Write-Host ('  answerIsJson (estricta) en los turnos largos: {0}' -f (@($largos | Where-Object { $_.answerIsJson }).Count))
Write-Host ("Duracion total: {0:N1} minutos" -f ((Get-Date) - $inicio).TotalMinutes)
